package main
import("bytes";"encoding/json";"fmt";"go/ast";"go/importer";"go/parser";"go/printer";"go/token";"go/types";"io";"os";"os/exec";"path/filepath";"strings")
type Export struct {ImportPath,Export string;GoFiles []string;Dir string}
type Site struct {File string `json:"file"`;Line int `json:"line"`;Function string `json:"function"`;Expression string `json:"expression"`;From string `json:"from"`;To string `json:"to"`;Float bool `json:"from_float"`}
func main(){c:=exec.Command("go","list","-export","-json","-deps","./v206");b,e:=c.Output();if e!=nil{panic(e)};d:=json.NewDecoder(bytes.NewReader(b));exports:=map[string]string{};var pkg Export;for{var x Export;e=d.Decode(&x);if e==io.EOF{break};if e!=nil{panic(e)};exports[x.ImportPath]=x.Export;if strings.HasSuffix(x.ImportPath,"/jsonata/v206"){pkg=x}}
 fs:=token.NewFileSet();files:=[]*ast.File{};for _,f:=range pkg.GoFiles{node,e:=parser.ParseFile(fs,filepath.Join(pkg.Dir,f),nil,0);if e!=nil{panic(e)};files=append(files,node)}
 imp:=importer.ForCompiler(fs,"gc",func(path string)(io.ReadCloser,error){return os.Open(exports[path])});info:=&types.Info{Types:map[ast.Expr]types.TypeAndValue{}};conf:=types.Config{Importer:imp,Sizes:types.SizesFor("gc","arm64")};_,e=conf.Check(pkg.ImportPath,fs,files,info);if e!=nil{panic(e)}
 sites:=[]Site{};for _,f:=range files{for _,decl:=range f.Decls{fn,ok:=decl.(*ast.FuncDecl);var body ast.Node=decl;owner:="package-initializer";if ok{if fn.Body==nil{continue};body=fn.Body;owner=fn.Name.Name};closures:=map[*ast.FuncLit]string{};ast.Inspect(body,func(n ast.Node)bool{if a,ok:=n.(*ast.AssignStmt);ok{for i,r:=range a.Rhs{if l,ok:=r.(*ast.FuncLit);ok&&i<len(a.Lhs){var p bytes.Buffer;printer.Fprint(&p,fs,a.Lhs[i]);closures[l]=p.String()}}};return true});stack:=[]string{owner};var walk func(ast.Node);walk=func(n ast.Node){ast.Inspect(n,func(x ast.Node)bool{if x==nil{return true};if l,ok:=x.(*ast.FuncLit);ok{v:=closures[l];if v==""{v=fmt.Sprint("closure@",fs.Position(l.Pos()).Line)};stack=append(stack,v);walk(l.Body);stack=stack[:len(stack)-1];return false};call,ok:=x.(*ast.CallExpr);if !ok||len(call.Args)!=1||!info.Types[call.Fun].IsType(){return true};to,ok:=info.Types[call.Fun].Type.Underlying().(*types.Basic);if !ok||to.Info()&types.IsInteger==0{return true};from:=info.Types[call.Args[0]].Type;fb,ok:=from.Underlying().(*types.Basic);isFloat:=ok&&fb.Info()&types.IsFloat!=0;var p bytes.Buffer;printer.Fprint(&p,fs,call);pos:=fs.Position(call.Pos());sites=append(sites,Site{filepath.Base(pos.Filename),pos.Line,strings.Join(stack,"/"),p.String(),from.String(),info.Types[call.Fun].Type.String(),isFloat});return true})};walk(body)}};out:=map[string]interface{}{"package":pkg.ImportPath,"go_files":pkg.GoFiles,"sites":sites,"method":"go/types: all integer-target conversions in every production package file; closure ownership retained. Reachability and numeric parsing/native helpers are assessed separately."};enc:=json.NewEncoder(os.Stdout);enc.SetIndent("","  ");if e=enc.Encode(out);e!=nil{panic(e)}}
